INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simpson-i---il-videogioco-italy', 'NDS', 'Simpson, I - Il Videogioco (Italy)', '2007', 'Action', 'Electronic Arts', '2', 'Platform Action', 'Action / Platformer.', 'Help the Simpsons use their new powers to save the world.', 'Italian version of the satirical Simpson adventure.', 'I Simpson - Il Videogioco (Italy) lets you play as Homer, Marge, Bart, and Lisa. Each family member has unique abilities in this self-aware parody of the gaming industry.');
