INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smurfs-2-the-europe-enfrdeesitnlsvnoda', 'NDS', 'Smurfs 2, The (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2013', 'Platformer', 'Magic Pockets', '2', 'Cartoon Platformer', 'Action / Platformer.', 'Rescue Smurfette and defeat the evil Gargamel.', 'Movie-based adventure featuring the blue crew.', 'The Smurfs 2 (Europe) follows the plot of the second film. Explore Paris and the Smurf Village, using the special abilities of each Smurf to overcome obstacles.');
