INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snes-mario', 'NDS', 'SNES Mario', '1985', 'Platformer', 'Nintendo', '2', 'Classic Platformer', 'Platformer / Homebrew.', 'Play classic Mario levels on your DS.', 'Fan-made SNES style Mario experience.', 'SNES Mario is a tribute to the 16-bit era. Experience retro-style platforming with updated controls and a nostalgic feel that pays homage to the Italian plumber.');
