INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snk-vs-capcom---card-fighters-ds-usa-rev-1', 'NDS', 'SNK vs. Capcom - Card Fighters DS (USA) (Rev 1)', '2008', 'Card Game', 'SNK Playmore', '2', 'Card Battle', 'Card Battle / RPG.', 'Build a deck of fighters to win the tournament.', 'Revised North American edition (Rev 1).', 'This Revision 1 of Card Fighters DS (USA) fixes a major progression bug present in the original release, making it the definitive and functional version for collectors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snood-2---on-vacation-europe-enfrdeesit', 'NDS', 'Snood 2 - On Vacation (Europe) (En,Fr,De,Es,It)', '2006', 'Puzzle', 'Armored Games', '1', 'Match Puzzle', 'Puzzle.', 'Launch and match Snoods to clear the screen.', 'Vacation-themed bubble shooter for Europe.', 'Snood 2 - On Vacation (Europe) brings the classic PC addictive gameplay to DS. Aim your Snood and clear the board across various exotic locations in five languages.');
